import React, { useState } from "react";
import "./Preview.css";
import Navbar from "./Navbar";

function Preview({ data, onEdit, onConfirm, updateData }) {

  const [editField, setEditField] = useState(null);
  const [tempValue, setTempValue] = useState("");

  const handleEdit = (field, value) => {
    setEditField(field);
    setTempValue(value);
  };

  const handleSave = (field) => {
    updateData({
      ...data,
      [field]: tempValue
    });
    setEditField(null);
  };

  const handleLimitChange = (category, value) => {
    updateData({
      ...data,
      limits: {
        ...data.limits,
        [category]: value
      }
    });
  };

  return (
    <div className="preview-page">

      <Navbar title="Review Details" onBack={onEdit} />

      <div className="preview-container">
        <h1 className="preview-title">Review Your Setup</h1>
        <p className="preview-subtitle">
          Please confirm your details before proceeding
        </p>

        <div className="preview-card">

          {/* INCOME */}
          <div className="preview-row">
            <div className="label">Income Type</div>

            {editField === "income" ? (
              <>
                <input
                  value={tempValue}
                  onChange={(e) => setTempValue(e.target.value)}
                />
                <button onClick={() => handleSave("income")}>Save</button>
              </>
            ) : (
              <>
                <div className="value">{data.income}</div>
                <button onClick={() => handleEdit("income", data.income)}>
                  Edit
                </button>
              </>
            )}
          </div>

          {/* CATEGORIES */}
          <div className="preview-row">
            <div className="label">Selected Categories</div>
            <div className="value">
              {data.categories && data.categories.length > 0
                ? data.categories.join(", ")
                : "None Selected"}
            </div>
          </div>

          {/* BUDGET LIMITS */}
          <div className="preview-row">
            <div className="label">Budget Limits</div>

            <div className="value" style={{ width: "100%" }}>
              {data.categories && data.categories.length > 0 ? (
                data.categories.map((cat) => (
                  <div
                    key={cat}
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      marginBottom: "8px"
                    }}
                  >
                    <span>{cat}</span>

                    <input
                      type="number"
                      value={data.limits?.[cat] || ""}
                      onChange={(e) =>
                        handleLimitChange(cat, e.target.value)
                      }
                      style={{
                        width: "120px",
                        padding: "5px",
                        borderRadius: "6px"
                      }}
                    />
                  </div>
                ))
              ) : (
                <span>No categories selected</span>
              )}
            </div>
          </div>

        </div>

        {/* ACTION BUTTONS */}
        <div className="preview-actions">
          <button className="edit-btn" onClick={onEdit}>
            Edit Details
          </button>

          <button className="confirm-btn" onClick={onConfirm}>
            Continue to Dashboard
          </button>
        </div>
      </div>
    </div>
  );
}

export default Preview;
